<?php
namespace App\Controllers\Ledger;
use App\Controllers\System\LayoutController;use App\Services\Ledger\PeriodClosureService;use Core\DbPdo;use InvalidArgumentException;use Throwable;
class PeriodClosureController{
 private PeriodClosureService$service;private LayoutController$layout;public function __construct(){$pdo=DbPdo::conn();$this->service=new PeriodClosureService($pdo);$this->layout=new LayoutController($pdo);}public function check():void{$this->page('check','결산점검');}public function periods():void{$this->page('periods','회계기간 마감');}public function carryForward():void{$this->page('carry-forward','기초금액 이월');}public function apiList():void{$this->respond(fn()=>['success'=>true,'data'=>$this->service->list()]);}public function apiOptions():void{$this->respond(fn()=>['success'=>true,'data'=>$this->service->options()]);}public function apiCheck():void{$this->respond(fn()=>['success'=>true,'data'=>$this->service->check(trim((string)($_GET['company_id']??'')),(int)($_GET['fiscal_year']??0))]);}public function apiClose():void{$this->respond(fn()=>$this->service->close($this->input()));}public function apiReopen():void{$this->respond(fn()=>$this->service->reopen($this->input()));}public function apiCarryForward():void{$this->respond(fn()=>$this->service->carryForward($this->input()));}
 private function page(string$mode,string$title):void{$periodClosurePageMode=$mode;ob_start();require PROJECT_ROOT.'/app/views/ledger/period-closures/index.php';$content=ob_get_clean();$this->layout->render(['pageTitle'=>$title,'content'=>$content,'pageStyles'=>$pageStyles??'','pageScripts'=>$pageScripts??'','layoutOptions'=>$layoutOptions??[]]);}private function input():array{$data=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($data)?$data:$_POST;}private function respond(callable$c):void{try{$this->json($c());}catch(InvalidArgumentException$e){$this->json(['success'=>false,'message'=>$e->getMessage()],422);}catch(Throwable){$this->json(['success'=>false,'message'=>'결산관리 처리 중 오류가 발생했습니다.'],500);}}private function json(array$data,int$status=200):void{http_response_code($status);header('Content-Type: application/json; charset=UTF-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
}
